import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'content-type,x-api-key',
  'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
};

// HTML stored as base64 to avoid all escaping issues
const HTML_B64 = "";

function getHTML(): string {
  const bytes = atob(HTML_B64);
  return bytes;
}

serve(async (req: Request) => {
  const url = new URL(req.url);
  if (req.method === 'OPTIONS') return new Response(null, { headers: CORS });

  if (url.pathname.endsWith('/api/generate') && req.method === 'POST') {
    try {
      const { prompt } = await req.json();
      const apiKey = req.headers.get('x-api-key');
      if (!apiKey) return new Response(JSON.stringify({ error: 'API key required' }), {
        status: 401, headers: { ...CORS, 'Content-Type': 'application/json' }
      });
      const r = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': apiKey, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 900, messages: [{ role: 'user', content: prompt }] }),
      });
      const d = await r.json();
      if (d.error) return new Response(JSON.stringify({ error: d.error.message }), {
        status: 400, headers: { ...CORS, 'Content-Type': 'application/json' }
      });
      const text = (d.content || []).map((b: { text?: string }) => b.text || '').join('');
      return new Response(JSON.stringify({ text }), { headers: { ...CORS, 'Content-Type': 'application/json' } });
    } catch (e: unknown) {
      return new Response(JSON.stringify({ error: e instanceof Error ? e.message : 'Unknown' }), {
        status: 500, headers: { ...CORS, 'Content-Type': 'application/json' }
      });
    }
  }

  return new Response(getHTML(), {
    headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'no-cache', ...CORS }
  });
});
